ALTER TABLE "content"."header" ADD COLUMN "app_name" text;
ALTER TABLE "content"."header" ADD COLUMN "app_icon" integer;
CREATE TABLE "content"."header__nav__sub_nav" (
  "id" integer GENERATED ALWAYS AS IDENTITY,
  "component_uid" uuid NOT NULL,
  "parent_id" integer NOT NULL,
  "order_index" integer NOT NULL DEFAULT 0,
