UPDATE content.header__nav SET requires_role = NULL WHERE requires_role = '';
UPDATE content.header__nav__sub_navigation SET requires_role = NULL WHERE requires_role = '';
UPDATE content.page_cv_a__skill SET level = NULL WHERE level = '';

DO $$
DECLARE
  offending text;
BEGIN
  SELECT string_agg(found.line, '; ') INTO offending FROM (
    SELECT format('header__nav document %s: requires_role "%s"', h.document_id, n.requires_role) AS line
      FROM content.header__nav n JOIN content.header h ON h.id = n.parent_id
      WHERE n.requires_role NOT IN ('public', 'owner', 'admin', 'editor')
    UNION ALL
    SELECT format('header__nav__sub_navigation document %s: requires_role "%s"', h.document_id, s.requires_role)
      FROM content.header__nav__sub_navigation s
      JOIN content.header__nav n ON n.id = s.parent_id
      JOIN content.header h ON h.id = n.parent_id
      WHERE s.requires_role NOT IN ('public', 'owner', 'admin', 'editor')
    UNION ALL
    SELECT format('page_cv_a__skill document %s: level "%s"', p.document_id, k.level)
      FROM content.page_cv_a__skill k JOIN content.page_cv_a p ON p.id = k.parent_id
      WHERE k.level NOT IN ('Proficient', 'Intermediate', 'Working Knowledge', 'Others')
  ) AS found;
  IF offending IS NOT NULL THEN
    RAISE EXCEPTION 'Stored values outside the new options, fix them in cms-admin before deploying: %', offending;
  END IF;
END
$$;

UPDATE content.header SET app_name = name;

INSERT INTO content.header__nav__sub_nav (component_uid, parent_id, order_index, title, link, requires_role)
  SELECT component_uid, parent_id, order_index, title, link, requires_role
  FROM content.header__nav__sub_navigation
  ORDER BY id;

UPDATE content.header__nav AS n SET order_index = n.order_index + 1
  FROM content.header h
  WHERE h.id = n.parent_id AND btrim(coalesce(h.nav_cv_link, '')) <> '';

WITH cv_entry AS MATERIALIZED (
  SELECT document_id, gen_random_uuid() AS component_uid
  FROM (SELECT DISTINCT document_id FROM content.header WHERE btrim(coalesce(nav_cv_link, '')) <> '') AS documents
)
INSERT INTO content.header__nav (component_uid, parent_id, order_index, title, link, requires_role)
  SELECT e.component_uid, h.id, 0, h.nav_cv_link, '/cv', 'public'
  FROM content.header h JOIN cv_entry e ON e.document_id = h.document_id
  WHERE btrim(coalesce(h.nav_cv_link, '')) <> '';

WITH not_found_document AS MATERIALIZED (
  SELECT document_id, gen_random_uuid() AS new_document_id
  FROM (
    SELECT DISTINCT document_id FROM content.header
    WHERE btrim(coalesce(not_found_title, '')) <> '' OR btrim(coalesce(not_found_description, '')) <> ''
  ) AS documents
)
INSERT INTO content.module_not_found
  (document_id, version, published_at, locale, created_at, updated_at, created_by, updated_by, title, description)
  SELECT d.new_document_id, h.version, h.published_at, h.locale, h.created_at, h.updated_at, h.created_by, h.updated_by,
    h.not_found_title, h.not_found_description
  FROM content.header h JOIN not_found_document d ON d.document_id = h.document_id
  WHERE btrim(coalesce(h.not_found_title, '')) <> '' OR btrim(coalesce(h.not_found_description, '')) <> '';
-- Data step (end)

